/// 验证 10009 证书：签发者必须是 OPlus Service CA E1，有效期有效，签名由 CA E1 私钥验证通过。
pub fn verify_10009_cert(leaf_der: &[u8]) -> bool {
    let (_, leaf) = match parse_x509_certificate(leaf_der) {
        Ok(v) => v,
        Err(_) => return false,
    };
    let (_, ca) = match parse_x509_certificate(SERVICE_CA_E1_DER) {
        Ok(v) => v,
        Err(_) => return false,
    };
    // 1. 签发者必须是 OPlus Service CA E1
    if leaf.issuer().to_string() != ca.subject().to_string() {
        return false;
    }
    // 2. 有效期
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    if leaf.validity().not_before.timestamp() > now as i64
        || leaf.validity().not_after.timestamp() < now as i64
    {
        return false;
    }
    // 3. 用 CA E1 公钥验证叶证书的 TBS 签名
    let vk = match VerifyingKey::from_public_key_der(ca.public_key().raw) {
        Ok(v) => v,
        Err(_) => return false,
    };
    let sig = match Signature::from_der(&leaf.signature_value.data) {
        Ok(s) => s,
        Err(_) => return false,
    };
    vk.verify(leaf.tbs_certificate.as_ref(), &sig).is_ok()
}
